import{_ as e,o as a,c as r,a2 as l}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"通用再保险（General Re / Gen Re）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/通用再保险.md","filePath":"03_companies/通用再保险.md"}'),d={name:"03_companies/通用再保险.md"};function o(h,t,i,n,u,s){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="通用再保险-general-re-gen-re" tabindex="-1">通用再保险（General Re / Gen Re） <a class="header-anchor" href="#通用再保险-general-re-gen-re" aria-label="Permalink to &quot;通用再保险（General Re / Gen Re）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>General Reinsurance Corporation（Gen Re）</td></tr><tr><td>行业</td><td>再保险</td></tr><tr><td>成立年份</td><td>1921年</td></tr><tr><td>总部</td><td>康涅狄格州斯坦福德</td></tr><tr><td>伯克希尔持股</td><td>100%</td></tr><tr><td>收购价格</td><td>220亿美元（1998年12月21日完成交割）</td></tr><tr><td>现任CEO</td><td>Kara Raiguel（2016年至今）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>全球最大再保险公司之一，为各类保险公司提供风险转移和分散服务。业务覆盖人寿险、财产险、意外险、健康险等多个领域，在124个国家运营。除通用再保险主体外，还全资持有德国<a href="/search.html?q=科隆再保险">科隆再保险</a>（Cologne Re，成立于1846年，世界上最古老的再保险公司之一）。收购完成后，通用再保险一跃成为伯克希尔最大的&quot;本土&quot;浮存金来源，长期保持约200亿美元的浮存金规模。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="收购时间线" tabindex="-1">收购时间线 <a class="header-anchor" href="#收购时间线" aria-label="Permalink to &quot;收购时间线&quot;">​</a></h3><p><strong>1998年12月21日</strong>，伯克希尔以<strong>220亿美元</strong>完成收购，成为当时保险业最大并购之一。收购以伯克希尔股票支付（发行约27.22万股A股），导致流通股增加约21.8%。收购时通用再保险是美国最大的财产意外再保险公司，同时持有<a href="/search.html?q=科隆再保险">科隆再保险</a>82%的股权（后于2008年增持至100%，完成全资化）。</p><p>几十年年来，通用再保险公司的名字在再保险业代表质量、诚信和专业——在<a href="/04_people/罗恩·弗格森.html">罗恩·弗格森</a>的领导下，这一声誉更加闪耀。（1998年股东信）</p><h3 id="整合困难期-1998—2002" tabindex="-1">整合困难期（1998—2002） <a class="header-anchor" href="#整合困难期-1998—2002" aria-label="Permalink to &quot;整合困难期（1998—2002）&quot;">​</a></h3><p>收购后的整合远未达到预期，通用再保险在最初几年成为伯克希尔的&quot;问题儿童&quot;：</p><ul><li><strong>1998年</strong>：收购完成当年即出现承保亏损，拉低了整体每股营业收益。巴菲特坦言：&quot;如果我们没有收购通用再保险公司，每股营业收益会显示适度增长。&quot;</li><li><strong>1999年</strong>：出现巨额承保亏损，公司在国内外市场均定价严重不足。巴菲特预计：&quot;除非发生特大灾难，我们预计2001年浮存金成本将下降——也许大幅下降——很大程度上是因为通用再保险的价格修正应该会在年内越来越明显地感受到。&quot;</li><li><strong>2000年</strong>：开始价格修正，淘汰严重无利可图的业务；浮存金成本高达6%（此前多年接近零）。<a href="/04_people/罗恩·弗格森.html">罗恩·弗格森</a>团队&quot;做出艰难的决定&quot;，被查理和巴菲特称许。</li><li><strong>2001年9月11日</strong>：灾难性打击。公司在恐怖主义风险定价上&quot;危险地薄弱&quot;，既忽视又否定大规模恐怖袭击的可能性。巴菲特公开承认：&quot;我让它以危险的风险水平运营——尤其是在通用再保险。我很遗憾地说，我们尚未获得补偿的大量风险仍留在我们的账本上，但它每天都在逐渐消散。&quot;同年末，<a href="/search.html?q=乔·布兰登">乔·布兰登</a>（Joe Brandon）临危受命接任CEO，塔德·蒙特罗斯（Tad Montross）担任总裁。准备金问题大规模暴露：实际发生于早年但未及时记录的损失高达8亿美元，2002年被补提入账。</li><li><strong>2002年</strong>：为纠正早年准备金错误额外计提13.1亿美元。巴菲特坦言：&quot;我希望我现在不知道我当时不知道的事情。&quot;</li></ul><p>巴菲特2002年在股东信中深刻反思：</p><blockquote><p>我完全错了。通用再保险的文化和做法已发生实质性变化，在管理层和我的不知情下，该公司严重错误定价其当前业务。此外，通用再保险积累了风险聚集，如果恐怖分子在美国引爆几枚大规模核弹，这本应是致命的。</p></blockquote><p>但他也表示乐观：&quot;我很幸运：乔和塔德就在手边，刚获得更大的权力，渴望迅速纠正过去的错误。&quot;</p><h3 id="整顿与重建-2003—2007" tabindex="-1">整顿与重建（2003—2007） <a class="header-anchor" href="#整顿与重建-2003—2007" aria-label="Permalink to &quot;整顿与重建（2003—2007）&quot;">​</a></h3><p><a href="/search.html?q=乔·布兰登">乔·布兰登</a>和<a href="/search.html?q=塔德·蒙特罗斯">塔德·蒙特罗斯</a>大刀阔斧重建承保纪律：</p><ul><li>坚持&quot;只承保定价合理的业务，无论对业务量有何影响&quot;——乔和塔德仅以承保盈利能力来评判自己</li><li>大量削减定价不足的业务</li><li>消除致命风险聚集（&quot;如果通用再保险保持独立，仅世贸中心袭击就足以威胁公司的生存&quot;）</li><li>2003年，竞争对手纷纷被降级，通用再保险成为全球主要再保险公司中<strong>唯一的AAA评级</strong>公司</li><li>2003年，巴菲特评价：&quot;Gen Re修复好了。感谢其CEO乔·布兰登及其合伙人塔德·蒙特罗斯……当保险公司购买再保险时，他们只购买一个承诺——一个可能几十年都不会被验证的承诺——在再保险世界中，没有比Gen Re和国民赔偿公司提供的承诺更好的了。&quot;</li><li>2005年，异常飓风季造成行业巨额损失，通用再保险承保亏损3.34亿美元，但&quot;考虑到肆虐行业的异常飓风损失，两个部门在2005年都表现良好&quot;（2005年信）</li><li>2005年，衍生品业务（Gen Re Securities）清盘继续税前亏损1.04亿美元，累计已达4.04亿美元。巴菲特公开忏悔：&quot;由于我没有立即关闭通用再保险交易部门，我让你们损失了很多钱。&quot;</li><li><strong>2006年</strong>：衍生品业务基本清盘完毕，累计税前损失4.09亿美元。巴菲特宣布：&quot;这将是我最后一次讨论通用再保险衍生品业务的损失。&quot;（2006年信）</li><li>2007年，巴菲特写道： <blockquote><p>几十年来，通用再保险一直是再保险人中的蒂芙尼，所有人都赞赏它的承保技能和纪律。不幸的是，这种名声在我1998年决定合并通用再保险的时候，已经不符合事实了，这个flaw（缺陷）我完全没发现。现在，感谢CEO乔·布兰登和他搭档塔德·蒙特罗斯，这家公司光泽已经恢复。</p></blockquote></li></ul><h3 id="稳定贡献期-2008—至今" tabindex="-1">稳定贡献期（2008—至今） <a class="header-anchor" href="#稳定贡献期-2008—至今" aria-label="Permalink to &quot;稳定贡献期（2008—至今）&quot;">​</a></h3><ul><li><strong>2008年</strong>：<a href="/search.html?q=乔·布兰登">乔·布兰登</a>退休，<a href="/search.html?q=塔德·蒙特罗斯">塔德·蒙特罗斯</a>接任CEO。巴菲特评价：&quot;乔纠正了船舵，我们相信通用再保未来在泰德手里掌握得很好。&quot;同年，伯克希尔将<a href="/search.html?q=科隆再保险">科隆再保险</a>持股从82%增持至100%，实现完全控股。</li><li><strong>2009年</strong>：巴菲特称通用再保险已从困境中的&quot;问题儿童&quot;变为保险板块的&quot;璀璨明珠&quot;。塔德及其团队还打造了重要的人寿再保险业务。</li><li><strong>2010—2015年</strong>：连续多年保持承保盈利，浮存金长期维持在200亿美元左右且成本低于零（负成本）。巴菲特多次称赞<a href="/search.html?q=塔德·蒙特罗斯">塔德·蒙特罗斯</a>遵守了&quot;所有四条保险诫命&quot;：&quot;在他领导下，通用再保险的巨额浮存金一直优于无成本。&quot;</li><li><strong>2016年</strong>：<a href="/search.html?q=塔德·蒙特罗斯">塔德·蒙特罗斯</a>退休（39年从业经验），Kara Raiguel接任CEO。Raiguel此前与<a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a>共事16年，具备深厚的保险精算背景。巴菲特评价：&quot;Tad在各方面都是一流人才，我们欠他一大笔感谢。&quot;</li><li><strong>2016年至今</strong>：Kara Raiguel继续领导通用再保险稳健运营，保持行业领先地位。</li></ul><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><ol><li><strong>AAA评级</strong>：全球主要再保险公司中罕见的AAA评级，在财务实力方面独树一帜</li><li><strong>零成本浮存金</strong>：长期维持200亿美元左右浮存金，且成本持续低于零，为伯克希尔提供免费弹药</li><li><strong>全球品牌与分销网络</strong>：124个国家运营网络，历史近百年的品牌信誉</li><li><strong>伯克希尔背书</strong>：&quot;承诺好不好，取决于做出承诺的人或机构。&quot;通用再保险背后有AAA级伯克希尔撑腰——&quot;空袋子站不直&quot;，客户无需担忧偿付能力</li><li><strong>承保纪律文化</strong>：经历整顿后重建的纪律文化，只承保有利可图的业务</li></ol><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>我们带着历史上最优秀的企业和管理团队组合进入1999年。我们在1998年收购的两家公司——通用再保险公司和公务机航空公司——在各方面都是一流的。 ——1998年股东信</p></blockquote><blockquote><p>在通用再保险，消息变得相当好：罗恩·弗格森以及乔·布兰登、塔德·蒙特罗斯和一支才华横溢的支持团队在2000年采取了许多行动，使该公司的盈利能力恢复到过去的水平。 ——2000年股东信</p></blockquote><blockquote><p>我完全错了。通用再保险的文化和做法已发生实质性变化……如果通用再保险保持独立，仅世贸中心袭击就足以威胁公司的生存。 ——2002年股东信</p></blockquote><blockquote><p>Gen Re的财务实力——即使在我们开始2003年时已是再保险公司中无与伦比的——在年内进一步增强。在巨头中，通用再保险在财务实力方面现在独树一帜，全面AAA评级。 ——2003年股东信</p></blockquote><blockquote><p>由于我没有立即关闭通用再保险交易部门，我让你们损失了很多钱。 ——2005年股东信</p></blockquote><blockquote><p>几十年来，通用再保险一直是再保险人中的蒂芙尼……这个flaw我完全没发现。现在，感谢Joe Brandon和Tad Montross，这家公司光泽已经恢复。 ——2007年股东信</p></blockquote><blockquote><p>去年春天乔退休，泰德成为CEO，查理和我感谢乔纠正了船舵，我们相信通用再保未来在泰德手里掌握得很好。再保险是长期承诺业务。通用再保最棒的就是，它背后有AAA伯克希尔背书。本杰明·富兰克林曾经说过：&quot;空袋子站不直。&quot;通用再保险客户不用担心这个。 ——2008年股东信</p></blockquote><blockquote><p>几年前，通用再保险陷入困境，如今已成为保险板块的璀璨明珠。 ——2009年股东信</p></blockquote><blockquote><p>在我们收购后的最初几年，General Re是一个令人头疼的问题。现在它是一个宝藏。 ——2011年股东信</p></blockquote><blockquote><p>可以记得，在我们收购General Re后不久，该公司被问题困扰，导致评论员——以及我也曾短暂——认为我犯了一个巨大错误。那一天早已过去。General Re现在是宝石。 ——2013年股东信</p></blockquote><blockquote><p>不幸的是，在收购GEICO之后，我愚蠢地用伯克希尔哈撒韦股票——大量股票——在1998年底收购了General Reinsurance。发行272,200股伯克希尔哈撒韦股票来购买General Re是我犯下的一个可怕错误，这一行为使我们的流通股增加了高达21.8%。我的错误导致伯克希尔哈撒韦股东付出的远多于他们得到的。 ——2016年股东信</p></blockquote><h2 id="教训与反思" tabindex="-1">教训与反思 <a class="header-anchor" href="#教训与反思" aria-label="Permalink to &quot;教训与反思&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>教训</th></tr></thead><tbody><tr><td>支付价格过高</td><td>以伯克希尔股票支付，导致流通股大增21.8%；优质资产也需要合理价格</td></tr><tr><td>整合难度低估</td><td>大型并购需充分评估文化整合与业务协同</td></tr><tr><td>浮存金质量</td><td>规模不等于质量，浮存金成本比规模更重要</td></tr><tr><td>合约定价</td><td>再保险必须坚持承保纪律，&quot;不&quot;是承保人词汇中最重要的词</td></tr><tr><td>准备金管理</td><td>不知道自己的成本在任何业务中都会造成问题；长尾业务中对真实成本的无知是炸药</td></tr><tr><td>衍生品业务</td><td>对复杂衍生品组合的&quot;无法衡量或有效限制&quot;的风险视而不见，清盘代价高达4.09亿美元</td></tr><tr><td>承保文化衰退</td><td>收购前公司的文化和做法已实质变化，但管理层和股东均未及时察觉</td></tr><tr><td>风险聚集忽视</td><td>未能正确计提恐怖主义聚集风险，导致9·11损失远超预期</td></tr></tbody></table><p>巴菲特的核心教训：</p><blockquote><p>浮存金的规模并不等于浮存金的质量。在评估再保险公司时，承保纪律比浮存金数量更重要。</p></blockquote><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>承保利润/亏损</th><th>浮存金</th><th>备注</th></tr></thead><tbody><tr><td>1998</td><td>亏损</td><td>~227亿美元</td><td>收购年，当年即现承保亏损</td></tr><tr><td>1999</td><td>巨额亏损</td><td>~227亿美元</td><td>国内外市场定价严重不足</td></tr><tr><td>2000</td><td>亏损改善</td><td>~228亿美元</td><td>开始价格修正，浮存金成本6%</td></tr><tr><td>2001</td><td>严重亏损</td><td>~230亿美元</td><td>9·11冲击；准备金补提8亿美元</td></tr><tr><td>2002</td><td>额外13.1亿亏损</td><td>~412亿美元</td><td>准备金纠错；承保纪律重建</td></tr><tr><td>2003</td><td>盈利改善</td><td>~230亿美元</td><td>AAA评级；问题儿童变璀璨明珠</td></tr><tr><td>2004</td><td>良好</td><td>~229亿美元</td><td>飓风损失12.5亿美元，但再保险表现良好</td></tr><tr><td>2005</td><td>亏损3.34亿</td><td>~229亿美元</td><td>异常飓风季；衍生品清盘继续亏损</td></tr><tr><td>2006</td><td>盈利5.26亿</td><td>~228亿美元</td><td>衍生品清盘基本完成</td></tr><tr><td>2007</td><td>盈利5.55亿</td><td>~230亿美元</td><td>完全恢复光泽</td></tr><tr><td>2008</td><td>盈利3.42亿</td><td>~211亿美元</td><td>乔·布兰登退休，泰德接任</td></tr><tr><td>2009</td><td>盈利4.77亿</td><td>~210亿美元</td><td>科隆再保险100%控股</td></tr><tr><td>2010</td><td>盈利4.52亿</td><td>~200亿美元</td><td>持续稳定</td></tr><tr><td>2011</td><td>盈利1.44亿</td><td>~197亿美元</td><td>浮存金成本持续为负</td></tr><tr><td>2012</td><td>盈利3.55亿</td><td>~197亿美元</td><td>人寿再保险业务持续增长</td></tr><tr><td>2013</td><td>盈利2.83亿</td><td>~201亿美元</td><td>现在是&quot;宝石&quot;</td></tr><tr><td>2014</td><td>盈利2.77亿</td><td>~200亿美元</td><td>持续盈利</td></tr><tr><td>2015</td><td>盈利1.32亿</td><td>~193亿美元</td><td>持续稳定</td></tr><tr><td>2016</td><td>盈利1.90亿</td><td>~186亿美元</td><td>Kara Raiguel接任CEO</td></tr></tbody></table><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>时期</th><th>贡献</th></tr></thead><tbody><tr><td><a href="/04_people/罗恩·弗格森.html">罗恩·弗格森</a>（Ron Ferguson）</td><td>CEO</td><td>收购时在任至2001年</td><td>长期领导通用再保险，将公司声誉推向顶峰；收购后应对早期整合困难</td></tr><tr><td><a href="/search.html?q=乔·布兰登">乔·布兰登</a>（Joe Brandon）</td><td>CEO</td><td>2001—2008年</td><td>临危受命，大刀阔斧重建承保纪律，清除致命风险聚集，关闭衍生品业务</td></tr><tr><td><a href="/search.html?q=塔德·蒙特罗斯">塔德·蒙特罗斯</a>（Tad Montross）</td><td>CEO</td><td>2008—2016年</td><td>延续整顿成果，将公司打造为稳定盈利的&quot;璀璨明珠&quot;和&quot;宝石&quot;</td></tr><tr><td>Kara Raiguel</td><td>CEO</td><td>2016年至今</td><td>接替蒙特罗斯，与<a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a>共事16年，继续保持行业领先地位</td></tr></tbody></table><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1998年、1999年、2000年、2001年、2002年、2003年、2004年、2005年、2006年、2007年、2008年、2009年、2010年、2011年、2012年、2013年、2014年、2015年、2016年</p><p>（注：2017年后巴菲特在股东信中不再单独重点讨论通用再保险，将其视为已稳定的成熟业务。）</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> — 母公司</li><li><a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a> — 再保险业务另一支柱（<a href="/search.html?q=国民赔偿">国民赔偿</a>），曾协助通用再保险整顿</li><li><a href="/04_people/罗恩·弗格森.html">罗恩·弗格森</a> — 收购时的CEO</li><li><a href="/search.html?q=科隆再保险">科隆再保险</a> — 通用再保险全资子公司，世界上最古老的再保险公司</li><li><a href="/search.html?q=乔·布兰登">乔·布兰登</a> — 2001—2008年通用再保险CEO，整顿恢复的关键人物</li><li><a href="/search.html?q=塔德·蒙特罗斯">塔德·蒙特罗斯</a> — 2008—2016年通用再保险CEO</li></ul><hr><p><em>最后更新：2026-04-16</em></p><h2 id="相关信件" tabindex="-1">相关信件 <a class="header-anchor" href="#相关信件" aria-label="Permalink to &quot;相关信件&quot;">​</a></h2><ul><li><a href="./../01_letters/1998年/翻译.html">1998年</a></li><li><a href="./../01_letters/1999年/翻译.html">1999年</a></li><li><a href="./../01_letters/2000年/翻译.html">2000年</a></li><li><a href="./../01_letters/2001年/翻译.html">2001年</a></li><li><a href="./../01_letters/2002年/翻译.html">2002年</a></li><li><a href="./../01_letters/2003年/翻译.html">2003年</a></li><li><a href="./../01_letters/2004年/翻译.html">2004年</a></li><li><a href="./../01_letters/2005年/翻译.html">2005年</a></li><li><a href="./../01_letters/2006年/翻译.html">2006年</a></li><li><a href="./../01_letters/2007年/翻译.html">2007年</a></li><li><a href="./../01_letters/2008年/翻译.html">2008年</a></li><li><a href="./../01_letters/2009年/翻译.html">2009年</a></li><li><a href="./../01_letters/2010年/翻译.html">2010年</a></li><li><a href="./../01_letters/2011年/翻译.html">2011年</a></li><li><a href="./../01_letters/2012年/翻译.html">2012年</a></li><li><a href="./../01_letters/2013年/翻译.html">2013年</a></li><li><a href="./../01_letters/2014年/翻译.html">2014年</a></li><li><a href="./../01_letters/2015年/翻译.html">2015年</a></li><li><a href="./../01_letters/2016年/翻译.html">2016年</a></li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1985年/翻译.html">/01_letters/1985年/翻译</a></li><li><a href="/01_letters/1998年/翻译.html">/01_letters/1998年/翻译</a></li><li><a href="/01_letters/2012年/翻译.html">/01_letters/2012年/翻译</a></li><li><a href="/01_letters/2013年/翻译.html">/01_letters/2013年/翻译</a></li></ul>',54)])])}const b=e(d,[["render",o]]);export{c as __pageData,b as default};
